function maxGigProfit(start: number[], end: number[], pay: number[]): number {
  const idx = start.map((_, i) => i).sort((a, b) => end[a] - end[b]);
  const n = idx.length;
  const ends = idx.map(i => end[i]);
  const best = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    const g = idx[i - 1];
    // j = number of gigs whose end <= start[g]
    let lo = 0, hi = i - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (ends[mid] <= start[g]) lo = mid + 1;
      else hi = mid;
    }
    best[i] = Math.max(best[i - 1], pay[g] + best[lo]);
  }
  return best[n];
}

